/* ================= 季節・隠し演出 ================= */
function secretToday(){ var d = new Date(), m = d.getMonth() + 1, dd = d.getDate(), md = m * 100 + dd, b = ls('wq.fx.bday'); if(b && b.slice(5).replace('-', '') == String(m).padStart(2, '0') + String(dd).padStart(2, '0')) return 'bday'; if(md >= 1228 && md <= 1231) return 'joya'; if(md >= 101 && md <= 107) return 'newyear'; if(md >= 1224 && md <= 1225) return 'xmas'; if(md >= 813 && md <= 816) return 'obon'; return ''; }
function playSecret(s, o){ if(s === 'joya') FX.joya.fn(o); else if(s === 'newyear') FX.newyear.fn(o); else if(s === 'xmas'){ FX.goldtext.fn({ word:'Merry Christmas' }); FX.season.fn(o); } else if(s === 'obon'){ FX.fireworks.fn({ count:4 }); FX.goldtext.fn({ word:'お盆もおつかれさま' }); } else { FX.goldrain.fn(o); FX.goldtext.fn({ word:'お誕生日おめでとう' }); FX.fireworks.fn({ count:4 }); } }

