var CATS = [['save', '保存・控え'], ['sent', '送付済・送った'], ['order', '受注'], ['bigorder', '大きい受注（100万円以上）'], ['pdf', 'PDF・印刷'], ['latest', '最新版・覚えた'], ['delivery', '配送・運賃・回送'], ['done', '締め完了・全部送付済'], ['complete', 'その他の完了（各アプリ）']];
